// ── Normalise data from Website Form ───────────────────
const body = $input.first().json.body || $input.first().json;

return [{
  json: {
    source: 'website_form',
    lead_name: body.name || body.full_name || 'there',
    lead_email: body.email || '',
    lead_phone: body.phone || body.phone_number || '',
    message: body.message || body.inquiry || body.details || '',
    property_interest: body.property || body.property_type || body.listing || '',
    budget: body.budget || '',
    preferred_contact: body.preferred_contact || 'email'
  }
}];

// ── Normalise data from WhatsApp via Twilio ────────────
const body = $input.first().json.body || $input.first().json;

const phone = (body.From || '').replace('whatsapp:', '');

return [{
  json: {
    source: 'whatsapp',
    lead_name: body.ProfileName || 'there',
    lead_email: '',
    lead_phone: phone,
    message: body.Body || '',
    property_interest: '',
    budget: '',
    preferred_contact: 'whatsapp',
    business_phone: (body.To || '').replace('whatsapp:', '')
  }
}];

// ── Normalise Email Lead ───────────────────────────────
const email = $input.first().json;

// Get email body
const body =
  email.text ||
  email.snippet ||
  email.html ||
  email.body ||
  "";

// Extract phone number
const phoneMatch = body.match(/(\+?\d[\d\s-]{8,}\d)/);

// Extract sender name (usually appears after "Thanks,")
const nameMatch = body.match(/Thanks,?\s*\n+\s*([^\n]+)/i);

const leadName = nameMatch?.[1]?.trim() || "Unknown Lead";
const leadPhone = phoneMatch?.[1]?.trim() || "";

// Extract email address if available
const senderEmail =
  email.from?.email ||
  email.sender?.email ||
  email.email ||
  "";

// Extract property type
let propertyInterest = "";

if (/2\s*bedroom/i.test(body)) {
  propertyInterest = "2 Bedroom Flat";
}

// Extract location
let location = "";

if (/Victoria Island/i.test(body)) {
  location = "Victoria Island";
}

// Extract budget
const budgetMatch = body.match(/budget\s+is\s+(.+?)(?:\.|\n)/i);

return [
  {
    json: {
      source: "email",
      lead_name: leadName,
      lead_email: senderEmail,
      lead_phone: leadPhone,
      property_interest: propertyInterest,
      location,
      budget: budgetMatch?.[1]?.trim() || "",
      preferred_contact: "phone",
      thread_id: email.threadId || email.id || "",
      message: body
    }
  }
];

// ── Merge point — add unified fields ────────────────────
function formatDate(date) {
  const d = new Date(date);
  return String(d.getDate()).padStart(2,'0') + '/' +
         String(d.getMonth()+1).padStart(2,'0') + '/' +
         d.getFullYear();
}

const data = $input.first().json;
const leadId = 'LEAD-' + Date.now().toString().slice(-7);
const now = new Date();
const hour = now.getHours();
const greeting = hour < 12 ? 'Good morning' : hour < 17 ? 'Good afternoon' : 'Good evening';

return [{
  json: {
    ...data,
    lead_id: leadId,
    received_at: formatDate(now),
    greeting: greeting
  }
}];

// ── Get AI Agent output ─────────────────────────────────
const agentOutput = $input.first().json.output || $input.first().json;
const leadData = $('Assign Lead ID').first().json;

// ── Parse the JSON from agent output ────────────────────
let analysis;
try {
  const raw = typeof agentOutput === 'string' ? agentOutput : JSON.stringify(agentOutput);
  const cleaned = raw.replace(/```json|```/g, '').trim();
  analysis = JSON.parse(cleaned);
} catch(e) {
  // If agent already returned a parsed object
  if (typeof agentOutput === 'object' && agentOutput.reply_message) {
    analysis = agentOutput;
  } else {
    analysis = {
      reply_message: `Hi ${leadData.lead_name}, thank you for reaching out. One of our agents will get back to you shortly to discuss your needs.`,
      urgency_level: 'WARM',
      lead_summary: 'Inquiry received, AI parsing failed.',
      suggested_followup: 'Manual review required.'
    };
  }
}

// ── Clean markdown from reply ────────────────────────────
const cleanReply = (analysis.reply_message || '')
  .replace(/\*\*/g, '')
  .replace(/\*/g, '')
  .replace(/#{1,6}\s/g, '')
  .trim();

// ── Normalise urgency level ──────────────────────────────
const urgency = (analysis.urgency_level || 'WARM').toUpperCase();

return [{
  json: {
    ...leadData,
    ai_reply: cleanReply,
    urgency_level: urgency,
    lead_summary: analysis.lead_summary || '',
    suggested_followup: analysis.suggested_followup || ''
  }
}];

